@import "@fontsource-variable/inter";
@import "@fontsource-variable/outfit";
@import "@fontsource-variable/jetbrains-mono";

/* Light sibling: a white page, #f5f5f5 panels and #f0f0f0 wells, black headings and buttons,
   #666 body copy, #ebebeb hairlines; the same blue. */
:root {
  --background: #ffffff;
  --foreground: #000000;
  --card: #f5f5f5;
  --card-foreground: #000000;
  --popover: #ffffff;
  --popover-foreground: #000000;
  --primary: #000000;
  --primary-foreground: #ffffff;
  --secondary: #f0f0f0;
  --secondary-foreground: #000000;
  --muted: #f0f0f0;
  --muted-foreground: #666666;
  --accent: #e8e8e8;
  --accent-foreground: #000000;
  --destructive: #e5484d;
  --destructive-foreground: #ffffff;
  --border: #ebebeb;
  --input: #e0e0e0;
  --ring: #0099ff;
  --highlight: #0088ee;
  --highlight-foreground: #ffffff;
  --glow: #0099ff;
  --chart-1: #0099ff;
  --chart-2: #8855ff;
  --chart-3: #00bb88;
  --chart-4: #d67a5c;
  --chart-5: #ffbb00;
  --sidebar: #f5f5f5;
  --sidebar-foreground: #000000;
  --sidebar-primary: #000000;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #e8e8e8;
  --sidebar-accent-foreground: #000000;
  --sidebar-border: #ebebeb;
  --sidebar-ring: #0099ff;

  --typeface-body: "Inter Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Outfit Variable", "Inter Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: "JetBrains Mono Variable", ui-monospace, SFMono-Regular, Menlo, monospace;
  --radius: 0.5rem;
  --page-width: 75rem;
  --page-gutter: 1.25rem;
  --section-y: 7.5rem;
}

/* Dark (faithful): #000 page; #111 side panels and windows, #171717 media wells, #1a1a1a
   quiet buttons and hairlines, #1f1f1f inner wells. White headings and buttons (black text),
   white at 60% (#999) for body copy. Framer-style blue #0099ff only in small touches. */
.dark {
  --background: #000000;
  --foreground: #ffffff;
  --card: #111111;
  --card-foreground: #ffffff;
  --popover: #111111;
  --popover-foreground: #ffffff;
  --primary: #ffffff;
  --primary-foreground: #000000;
  --secondary: #1a1a1a;
  --secondary-foreground: #ffffff;
  --muted: #171717;
  --muted-foreground: #999999;
  --accent: #242424;
  --accent-foreground: #ffffff;
  --destructive: #ff5f57;
  --destructive-foreground: #000000;
  --border: #1a1a1a;
  --input: #242424;
  --ring: #0099ff;
  --highlight: #0099ff;
  --highlight-foreground: #ffffff;
  --glow: #0a84ff;
  --chart-1: #0099ff;
  --chart-2: #8855ff;
  --chart-3: #00bb88;
  --chart-4: #d67a5c;
  --chart-5: #ffbb00;
  --sidebar: #111111;
  --sidebar-foreground: #ffffff;
  --sidebar-primary: #ffffff;
  --sidebar-primary-foreground: #000000;
  --sidebar-accent: #1f1f1f;
  --sidebar-accent-foreground: #ffffff;
  --sidebar-border: #1a1a1a;
  --sidebar-ring: #0099ff;
}
